import{z as i,x as o,o as s,c as d,q as r,j as l,D as e,d as n,s as B,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"可测性设计与扫描链","description":"","frontmatter":{"title":"可测性设计与扫描链","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dft-scan-chain.md","filePath":"cs/dft-scan-chain.md","lastUpdated":1791063341000}'),p={name:"cs/dft-scan-chain.md"};function F(c,a,T,h,D,m){const t=o("Mermaid");return s(),d("div",null,[a[2]||(a[2]=r('<h1 id="可测性设计与扫描链" tabindex="-1">可测性设计与扫描链 <a class="header-anchor" href="#可测性设计与扫描链" aria-label="Permalink to &quot;可测性设计与扫描链&quot;">​</a></h1><div class="epigraph"><p>封装之后没有探针扎到每个触发器；把 FF 串成移位寄存器，测试仪才能移入向量、移出响应，判断组合逻辑是否粘死。</p><footer>—— 据 Bushnell and Agrawal, Essentials of Electronic Testing；IEEE Std 1149.1（JTAG）；Weste and Harris, CMOS VLSI Design 整理</footer></div><p><a href="/cs/formal-equivalence">上一课</a>保证网表与 RTL 一致，不保证<strong>硅</strong>无缺陷。<a href="/cs/moore-law-economics">摩尔经济学</a>把测试成本算进单价。缺口是 <strong>DFT</strong>：扫描链把触发器变成可控可观，否则自动测试仪（ATE）够不着内部节点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定故障（stuck-at）模型：某网恒 0/1。要激活故障并传播到可观察点。全组合电路还可用输入直接控；时序电路状态空间太大。扫描：每只 FF 加 MUX，测试模式时 D 来自上一只 FF 的 Q，链成移位寄存器。缺口不是再做 LEC，而是这套测试结构如何插入、如何与功能时钟共存。</p><p><span class="marginnote">术语翻译：「固定故障 stuck-at」是给物理缺陷起的模型化外号——某根线因制造缺陷永远读作 0 或 1，好比电线焊死在电源或地上。真实缺陷千奇百怪，但这个最简单的模型能抓住大多数，ATPG 就是按它来出题的。</span></p><p>IEEE 1149.1 JTAG 提供芯片级 TAP，边界扫描测引脚与板级互连；内部扫描是同一思想往里走。</p><h3 id="扫描不是「功能复位」" tabindex="-1">扫描不是「功能复位」 <a class="header-anchor" href="#扫描不是「功能复位」" aria-label="Permalink to &quot;扫描不是「功能复位」&quot;">​</a></h3><p>扫描移位时状态无功能含义，翻转率高、功耗大，须遵守测试功耗预算。功能复位树在测试模式可能被旁路。把扫描使能当复位，量产测试会破坏芯片或给出假失败。</p><p><span class="marginnote">常见误区：把扫描使能当成一种复位。移位阶段寄存器里全是无功能含义的乱码；若这时误触发功能复位逻辑、或让时钟门控把时钟关了，捕获到的响应全错，量产测试会成批「假失败」。所以 scan-enable 是独立控制信号，有自己单独的时序约束。</span></p><p><span class="marginnote">Bushnell/Agrawal 是测试教材。1149.1 是边界扫描标准。Weste/Harris 有扫描 FF 电路。本课不背全部故障模型（转换延迟故障点名即可）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>综合后插入扫描 FF 与链。ATE：scan-in 一向量，脉冲一次功能捕获，scan-out。ATPG 生成向量。约束：扫描链时钟、锁存器电平敏感扫描（LSSD）是另一风格。与 <a href="/cs/sta">STA</a>：扫描移位路径有自己的时序，常更慢，单独约束。</p>',13)),(s(),l(A,null,{default:e(()=>[B(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20FF%5B%22%E5%8A%9F%E8%83%BD%20FF%22%5D%20--%3E%20MUX%5B%22%E6%B5%8B%E8%AF%95%20MUX%22%5D%0A%20%20MUX%20--%3E%20CHAIN%5B%22%E6%89%AB%E6%8F%8F%E9%93%BE%22%5D%0A%20%20CHAIN%20--%3E%20ATE%5B%22%E7%A7%BB%E5%85%A5%20%2F%20%E6%8D%95%E8%8E%B7%20%2F%20%E7%A7%BB%E5%87%BA%22%5D%0A%20%20ATE%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ABIST%20%E6%8A%8A%20ATE%20%E6%90%AC%E8%BF%9B%E8%8A%AF%E7%89%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"算术单元的宽乘法器组合锥正是 ATPG 的负担；测试点插入可提高覆盖。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"下一课 BIST 用片上图案生成器减少 ATE 数据量。扫描改变网表，必须再 LEC（功能模式 scan-enable=0）。时钟门控在测试中强制开。复位与扫描冲突由 DFT 规范定义。",-1)),a[6]||(a[6]=E("p",null,"上一张图画「扫描结构如何插进芯片」；这张回答运行时的问题：scan_enable 一换挡，FF 的 D 从哪来，一个向量又分哪三步执行。",-1)),(s(),l(A,null,{default:e(()=>[B(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SE%5B%22scan_enable%20%E4%BF%A1%E5%8F%B7%22%5D%20--%20%220%20%E5%8A%9F%E8%83%BD%E6%A8%A1%E5%BC%8F%22%20--%3E%20FN%5B%22MUX%20%E9%80%89%E5%8A%9F%E8%83%BD%E9%80%BB%E8%BE%91%E9%80%81%E6%9D%A5%E7%9A%84%20D%22%5D%0A%20%20SE%20--%20%221%20%E6%B5%8B%E8%AF%95%E6%A8%A1%E5%BC%8F%22%20--%3E%20TS%5B%22MUX%20%E9%80%89%E4%B8%8A%E4%B8%80%E7%BA%A7%20FF%20%E7%9A%84%20Q%22%5D%0A%20%20TS%20--%3E%20PH1%5B%22%E9%98%B6%E6%AE%B5%E4%B8%80%20%E7%A7%BB%E4%BD%8D%20%E7%81%8C%E5%85%A5%E6%B5%8B%E8%AF%95%E5%90%91%E9%87%8F%22%5D%0A%20%20PH1%20--%3E%20PH2%5B%22%E9%98%B6%E6%AE%B5%E4%BA%8C%20%E6%8D%95%E8%8E%B7%20%E6%89%93%E4%B8%80%E4%B8%AA%E5%8A%9F%E8%83%BD%E6%97%B6%E9%92%9F%22%5D%0A%20%20PH2%20--%3E%20PH3%5B%22%E9%98%B6%E6%AE%B5%E4%B8%89%20%E7%A7%BB%E4%BD%8D%20%E7%A7%BB%E5%87%BA%E5%93%8D%E5%BA%94%E6%AF%94%E5%AF%B9%22%5D%0A%20%20PH3%20--%3E%20REP%5B%22%E5%9B%9E%E5%88%B0%E9%98%B6%E6%AE%B5%E4%B8%80%20%E9%80%81%E4%B8%8B%E4%B8%80%E4%B8%AA%E5%90%91%E9%87%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">数字实例：扫描链像给芯片插了根吸管——测试仪不用探进内部，而是把一串 0/1 从链头灌进去、从链尾吸出来。链上 1000 只 FF 时，一个向量光移位就要约 2000 拍（移入加移出），这正是测试时间与向量数都算成本的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写模拟 BIST、不把系统级软件测试当 DFT。不讨论故障定位的软件算法细节。不进入封装探针卡机械。</p><p>后课默认：量产数字测试依赖扫描链把 FF 串起来；JTAG 管边界；内部还有 BIST。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>封装后靠扫描移位控/观内部 FF。</li><li>插入 MUX 改网表，功能模式须再等价检查。</li><li>测试功耗与扫描时序单独约束。</li><li>出处：Bushnell and Agrawal；IEEE 1149.1；Weste and Harris。</li></ul>',6))])}const S=i(p,[["render",F]]);export{f as __pageData,S as default};
